package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_append_TriageGen1Test {

    private Element root;

    @Before
    public void setUp() {
        root = new Element("div", "http://example.com");
    }

    @Test
    public void testAppendValidHtml() {
        String html = "<p>Test</p>";
        root.append(html);
        Elements children = root.children();
        assertEquals(1, children.size());
        assertEquals("p", children.first().tagName());
        assertEquals("Test", children.first().text());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAppendNullHtml() {
        root.append(null);
    }

    @Test
    public void testAppendEmptyHtml() {
        String html = "";
        root.append(html);
        assertEquals(0, root.children().size());
    }

    @Test
    public void testAppendMultipleNodes() {
        String html = "<p>First</p><p>Second</p>";
        root.append(html);
        Elements children = root.children();
        assertEquals(2, children.size());
        assertEquals("First", children.get(0).text());
        assertEquals("Second", children.get(1).text());
    }

    @Test
    public void testAppendNestedHtml() {
        String html = "<div><p>Nested</p></div>";
        root.append(html);
        Elements children = root.children();
        assertEquals(1, children.size());
        Element div = children.first();
        assertEquals("div", div.tagName());
        assertEquals(1, div.children().size());
        assertEquals("p", div.child(0).tagName());
        assertEquals("Nested", div.child(0).text());
    }

    @Test
    public void testAppendWithExistingChildren() {
        root.appendChild(new Element("p", "http://example.com", null).text("Existing"));
        String html = "<span>New</span>";
        root.append(html);
        Elements children = root.children();
        assertEquals(2, children.size());
        assertEquals("p", children.get(0).tagName());
        assertEquals("Existing", children.get(0).text());
        assertEquals("span", children.get(1).tagName());
        assertEquals("New", children.get(1).text());
    }

    @Test
    public void testAppendWithInvalidHtml() {
        String html = "<p>Unclosed";
        root.append(html);
        Elements children = root.children();
        assertEquals(1, children.size());
        assertEquals("p", children.first().tagName());
        assertEquals("Unclosed", children.first().text());
    }
}
